/*
 * ClubEfootball - Tarefa 7
 * Versao autocontida: os 29.222 IDs validados estao embutidos neste arquivo.
 * V6: selecione a pasta comum coleta-efhub-dados-fotos; DADOS primeiro, FOTOS depois.
 * Cole este arquivo inteiro no Console do DevTools em https://efhub.com/pt-BR/players
 * Primeira execucao: await ClubEFT7.iniciar() (selecione Downloads/coleta-efhub-dados-fotos)
 * Retomada em uma linha: await ClubEFT7.retomar()
 *
 * Nao escreve no Supabase nem envia ao Cloudinary. Fotos sao baixadas somente apos comando explicito.
 * Cada execucao processa somente um lote, com no maximo 1.000 card_id.
 */

(() => {
  'use strict';

  const CONFIG = Object.freeze({
    schemaVersion: 't7-efhub-structured-data-and-photos-two-phase-folder-v6',
    datasetFile: 'embedded:IDS-FALTANTES-EFHUB.txt',
    datasetSha256: '143955ff35d922f5d6ff10ee9045f7f970fe35fe814e3781058a78aae4b66821',
    datasetTag: 'T7-EFHUB-DADOS-E-FOTOS-V6-143955ff-29222-IDS',
    impulseUniverse: 37743,
    expectedMissing: 29222,
    alreadyCompleteExcluded: 8521,
    batchSize: 1000,
    totalBatches: 30,
    endpointPath: (cardId) => `/api/public/players/${encodeURIComponent(cardId)}`,
    requiredOrigin: 'https://efhub.com',
    maxAttempts: 6,
    minIntervalMs: 5000,
    intervalJitterMs: 1500,
    probeSuccessPauseMs: 15000,
    requestTimeoutMs: 30000,
    retryBaseMs: 2000,
    retryMaxMs: 60000,
    throttleBaseMs: 60000,
    throttleMaxMs: 900000,
    imageMinIntervalMs: 1500,
    imageIntervalJitterMs: 750,
    imageRequestTimeoutMs: 45000,
    dbName: 'clubefootball-t7-efhub-fresh-v6',
    dbVersion: 1,
  });

  const EMBEDDED_IDS_BASE64 = '';

  const STAT_FIELDS = Object.freeze([
    'offensiveAwareness', 'ballControl', 'dribbling', 'tightPossession', 'lowPass',
    'loftedPass', 'finishing', 'heading', 'setPieceTaking', 'curl', 'speed',
    'acceleration', 'kickingPower', 'jump', 'physicalContact', 'balance', 'stamina',
    'defensiveAwareness', 'ballWinning', 'trackingBack', 'aggression', 'gkAwareness',
    'gkCatching', 'gkClearing', 'gkReflexes', 'gkReach',
  ]);

  const MODEL_FIELDS = Object.freeze([
    'armLength', 'shoulderWidth', 'neckLength', 'chestMeasurement', 'neckSize',
    'shoulderHeight', 'legLength', 'thighSize', 'waistSize', 'armSize', 'calfSize',
    'legCoverageRadius', 'armCoverageRadius', 'jumpingHeight', 'torsoCollision',
    'dribbleHeight',
  ]);

  const REQUIRED_KEYS = Object.freeze([
    'id', 'name', 'nameJa', 'nameZh', 'slug', 'nationality', 'nationalityCode',
    'countryId', 'team', 'teamId', 'league', 'leagueId', 'position',
    'additionalPositions', 'overallRating', 'age', 'height', 'weight',
    'preferredFoot', 'weakFootUsage', 'weakFootAccuracy', 'form', 'condition',
    'injuryResistance', 'skills', 'comSkills', 'stats', 'playerModel', 'imageUrl',
    'playerId', 'gpValue', 'datapackId', 'playerType', 'levelCap',
  ]);

  const REQUIRED_NONEMPTY = Object.freeze([
    'name', 'slug', 'position', 'overallRating', 'age', 'height', 'weight',
    'preferredFoot', 'weakFootUsage', 'weakFootAccuracy', 'form', 'condition',
    'injuryResistance', 'playerId', 'datapackId', 'playerType', 'levelCap',
  ]);

  const state = {
    paused: false,
    running: false,
    currentBatch: null,
    lastRequestStartedAt: 0,
    overlay: null,
    checkpointRepair: null,
    migratedPhotoState: false,
  };

  class BatchStopError extends Error {
    constructor(message) {
      super(message);
      this.name = 'BatchStopError';
    }
  }

  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

  function stableStringify(value) {
    if (value === null || typeof value !== 'object') return JSON.stringify(value);
    if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`).join(',')}}`;
  }

  async function sha256Text(text) {
    const bytes = new TextEncoder().encode(text);
    const hash = await crypto.subtle.digest('SHA-256', bytes);
    return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
  }

  async function sha256Bytes(bytes) {
    const hash = await crypto.subtle.digest('SHA-256', bytes);
    return [...new Uint8Array(hash)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
  }

  function normalizeCardId(value) {
    if (typeof value === 'bigint') return value.toString();
    if (typeof value === 'number' && Number.isSafeInteger(value)) return String(value);
    if (typeof value === 'string' && /^\d+$/.test(value.trim())) return value.trim();
    return null;
  }

  function unwrapPayload(raw) {
    const candidates = [...new Set([raw, raw?.player, raw?.data, raw?.data?.player]
      .filter((item) => item && typeof item === 'object' && !Array.isArray(item)))];
    const withIdentity = candidates.filter((item) => Object.prototype.hasOwnProperty.call(item, 'id'));
    if (withIdentity.length !== 1) {
      return { ok: false, classification: 'ambiguous_excluded', reason: `payload_identity_candidates:${withIdentity.length}` };
    }
    return { ok: true, payload: withIdentity[0] };
  }

  function isFiniteNumeric(value) {
    return typeof value === 'number' && Number.isFinite(value);
  }

  function validatePhoto(cardId, imageUrl) {
    const expected = `https://efimg.com/efootballhub22/images/player_cards/${cardId}_l.png`;
    if (typeof imageUrl !== 'string' || !imageUrl.trim()) {
      return { sourceUrl: null, observedUrl: imageUrl ?? null, status: 'missing' };
    }
    if (imageUrl === expected) {
      return { sourceUrl: imageUrl, observedUrl: imageUrl, status: 'validated_exact_card_id' };
    }
    return { sourceUrl: null, observedUrl: imageUrl, status: 'rejected_mismatch' };
  }

  function structuredPayloadWithoutEfootballDbOwnedFields(payload) {
    if (Array.isArray(payload)) return payload.map(structuredPayloadWithoutEfootballDbOwnedFields);
    if (!payload || typeof payload !== 'object') return payload;
    return Object.fromEntries(Object.entries(payload)
      .filter(([key]) => !/^(?:boost|booster|box|pack)/i.test(key))
      .map(([key, value]) => [key, structuredPayloadWithoutEfootballDbOwnedFields(value)]));
  }

  function photoFileName(cardId) {
    if (!/^\d+$/.test(cardId)) throw new Error(`card_id invalido para foto: ${cardId}`);
    return `${cardId}_l.png`;
  }

  function validatePayload(requestedCardId, raw) {
    const unwrapped = unwrapPayload(raw);
    if (!unwrapped.ok) return unwrapped;
    const payload = unwrapped.payload;
    const payloadId = normalizeCardId(payload.id);
    if (!payloadId || payloadId !== requestedCardId) {
      return {
        ok: false,
        classification: 'ambiguous_excluded',
        reason: 'payload_id_mismatch',
        requested_card_id: requestedCardId,
        observed_id: payloadId,
      };
    }

    const missing = REQUIRED_KEYS.filter((key) => !Object.prototype.hasOwnProperty.call(payload, key));
    const empty = REQUIRED_NONEMPTY.filter((key) => payload[key] === null || payload[key] === undefined || payload[key] === '');
    const invalidArrays = ['additionalPositions', 'skills', 'comSkills'].filter((key) => !Array.isArray(payload[key]));
    const invalidStats = STAT_FIELDS.filter((key) => !isFiniteNumeric(payload.stats?.[key]));
    const invalidModel = MODEL_FIELDS.filter((key) => !isFiniteNumeric(payload.playerModel?.[key]));

    if (missing.length || empty.length || invalidArrays.length || invalidStats.length || invalidModel.length) {
      return {
        ok: false,
        classification: 'failed',
        reason: 'incomplete_structured_payload',
        details: { missing, empty, invalidArrays, invalidStats, invalidModel },
      };
    }
    return { ok: true, payload, photo: validatePhoto(requestedCardId, payload.imageUrl) };
  }

  function classifyHttp(statusCode) {
    if (statusCode >= 200 && statusCode < 300) return 'success';
    if (statusCode === 401 || statusCode === 403) return 'stop_batch';
    if (statusCode === 404 || statusCode === 410) return 'inactive_excluded';
    if (statusCode === 429) return 'throttle';
    if (statusCode === 408 || statusCode === 425 || statusCode >= 500) return 'retry';
    return 'failed';
  }

  function classifyImageHttp(statusCode) {
    if (statusCode === 429) return 'throttle_pending';
    if (statusCode === 404 || statusCode === 410) return 'unavailable';
    if (statusCode >= 200 && statusCode < 300) return 'download';
    return 'retry_pending';
  }

  function parseRetryAfter(value, nowMs = Date.now()) {
    if (value === null || value === undefined || String(value).trim() === '') return null;
    const text = String(value).trim();
    if (/^\d+(?:\.\d+)?$/.test(text)) return Math.max(0, Math.ceil(Number(text) * 1000));
    const dateMs = Date.parse(text);
    return Number.isFinite(dateMs) ? Math.max(0, dateMs - nowMs) : null;
  }

  function randomFraction() {
    const value = new Uint32Array(1);
    crypto.getRandomValues(value);
    return value[0] / 0x100000000;
  }

  function computeBackoffMs(attempt, retryAfterValue = null, nowMs = Date.now(), randomValue = randomFraction()) {
    const exponent = Math.max(0, Number(attempt) - 1);
    const exponential = Math.min(CONFIG.retryMaxMs, CONFIG.retryBaseMs * (2 ** exponent));
    const retryAfterMs = parseRetryAfter(retryAfterValue, nowMs) ?? 0;
    const jitter = Math.floor(exponential * 0.35 * Math.max(0, Math.min(1, randomValue)));
    return Math.max(retryAfterMs, exponential) + jitter;
  }

  function computeThrottleCooldownMs(consecutiveThrottles, retryAfterValue = null, nowMs = Date.now(), randomValue = randomFraction()) {
    const exponent = Math.max(0, Number(consecutiveThrottles) - 1);
    const exponential = Math.min(CONFIG.throttleMaxMs, CONFIG.throttleBaseMs * (2 ** exponent));
    const retryAfterMs = parseRetryAfter(retryAfterValue, nowMs) ?? 0;
    const jitter = Math.floor(exponential * 0.25 * Math.max(0, Math.min(1, randomValue)));
    return Math.max(retryAfterMs, exponential) + jitter;
  }

  function buildThrottleDecision(consecutiveThrottles, retryAfterValue = null, nowMs = Date.now(), randomValue = randomFraction()) {
    const cooldownMs = computeThrottleCooldownMs(consecutiveThrottles, retryAfterValue, nowMs, randomValue);
    return {
      http_status: 429,
      status: 'throttled_pending',
      terminal_failure: false,
      retry_after_observed: retryAfterValue,
      cooldown_ms: cooldownMs,
      cooldown_until_ms: nowMs + cooldownMs,
    };
  }

  function isThrottleFailureRecord(record) {
    if (!record || !['failed', 'in_progress'].includes(record.status)) return false;
    const evidence = [record.reason, record.last_error, record.http_status].filter((value) => value !== null && value !== undefined).join(' ');
    return /(?:HTTP\s*)?429|too many requests|throttl/i.test(evidence);
  }

  function recoverThrottleRecord(record, nowIso = new Date().toISOString()) {
    return {
      ...record,
      status: 'throttled_pending',
      attempts: 0,
      historical_attempts: (Number(record.historical_attempts) || 0) + (Number(record.attempts) || 0),
      recovered_from_status: record.status,
      recovered_from_reason: record.reason ?? record.last_error ?? 'HTTP 429',
      reason: 'recovered_transient_throttle',
      last_error: 'HTTP 429 recuperado; aguardando sonda unica.',
      updated_at: nowIso,
    };
  }

  function isV3FalseHttp200FailureRecord(record) {
    if (!record || record.status !== 'failed') return false;
    return Number(record.http_status) === 200 && /^HTTP\s+200$/i.test(String(record.reason ?? '').trim());
  }

  function isNonterminalNetworkFailureRecord(record) {
    if (!record || !['failed', 'in_progress'].includes(record.status)) return false;
    const evidence = [record.reason, record.last_error].filter(Boolean).join(' ');
    return /network:|invalid_json:|HTTP\s+(?:408|425|5\d\d)|retries_exhausted/i.test(evidence);
  }

  function checkpointRecoveryKind(record) {
    if (isV3FalseHttp200FailureRecord(record)) return 'v3_false_http_200';
    if (isThrottleFailureRecord(record)) return 'legacy_http_429';
    if (isNonterminalNetworkFailureRecord(record)) return 'transient_network_or_json';
    return null;
  }

  function recoverCheckpointRecord(record, kind = checkpointRecoveryKind(record), nowIso = new Date().toISOString()) {
    if (!kind) return record;
    const previousEvidence = {
      recovered_at: nowIso,
      kind,
      status: record.status,
      attempts: Number(record.attempts) || 0,
      reason: record.reason ?? null,
      last_error: record.last_error ?? null,
      http_status: record.http_status ?? null,
    };
    return {
      ...record,
      status: kind === 'legacy_http_429' ? 'throttled_pending' : 'transient_pending',
      attempts: 0,
      historical_attempts: (Number(record.historical_attempts) || 0) + (Number(record.attempts) || 0),
      recovery_history: [...(Array.isArray(record.recovery_history) ? record.recovery_history : []), previousEvidence],
      recovered_from_status: record.status,
      recovered_from_reason: record.reason ?? record.last_error ?? null,
      reason: kind === 'v3_false_http_200'
        ? 'recovered_v3_http_200_classifier_bug'
        : kind === 'legacy_http_429'
          ? 'recovered_transient_throttle'
          : 'recovered_transient_network_or_json',
      last_error: kind === 'v3_false_http_200'
        ? 'V3 classificou HTTP 200 antes do parsing; ID devolvido a pending sem rede.'
        : 'Falha transitoria recuperada; aguardando sonda unica.',
      terminal_failure: false,
      updated_at: nowIso,
    };
  }

  function batchForIndex(index) {
    return Math.floor(index / CONFIG.batchSize) + 1;
  }

  function idsForBatch(ids, batchNo) {
    if (!Number.isInteger(batchNo) || batchNo < 1 || batchNo > CONFIG.totalBatches) {
      throw new Error(`Lote invalido: ${batchNo}. Use 1 a ${CONFIG.totalBatches}.`);
    }
    return ids.slice((batchNo - 1) * CONFIG.batchSize, batchNo * CONFIG.batchSize);
  }

  function recordKey(cardId) {
    return `${CONFIG.datasetSha256}:${cardId}`;
  }

  function openDb() {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(CONFIG.dbName, CONFIG.dbVersion);
      request.onupgradeneeded = () => {
        const db = request.result;
        if (!db.objectStoreNames.contains('meta')) db.createObjectStore('meta', { keyPath: 'key' });
        if (!db.objectStoreNames.contains('records')) {
          const records = db.createObjectStore('records', { keyPath: 'key' });
          records.createIndex('dataset', 'datasetSha256', { unique: false });
          records.createIndex('status', 'status', { unique: false });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
  }

  async function idbGet(storeName, key) {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, 'readonly');
      const request = tx.objectStore(storeName).get(key);
      request.onsuccess = () => resolve(request.result ?? null);
      request.onerror = () => reject(request.error);
      tx.oncomplete = () => db.close();
    });
  }

  async function idbPut(storeName, value) {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, 'readwrite');
      tx.objectStore(storeName).put(value);
      tx.oncomplete = () => { db.close(); resolve(value); };
      tx.onerror = () => { db.close(); reject(tx.error); };
      tx.onabort = () => { db.close(); reject(tx.error); };
    });
  }

  async function idbDelete(storeName, key) {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction(storeName, 'readwrite');
      tx.objectStore(storeName).delete(key);
      tx.oncomplete = () => { db.close(); resolve(); };
      tx.onerror = () => { db.close(); reject(tx.error); };
    });
  }

  async function allDatasetRecords() {
    const db = await openDb();
    return new Promise((resolve, reject) => {
      const tx = db.transaction('records', 'readonly');
      const request = tx.objectStore('records').index('dataset').getAll(CONFIG.datasetSha256);
      request.onsuccess = () => resolve(request.result ?? []);
      request.onerror = () => reject(request.error);
      tx.oncomplete = () => db.close();
    });
  }

  const cooldownKey = (channel = 'data') => `cooldown-${channel}:${CONFIG.datasetSha256}`;
  const rateKey = () => `rate:${CONFIG.datasetSha256}`;
  const imageRateKey = () => `rate-image:${CONFIG.datasetSha256}`;

  async function repairCheckpointFailures() {
    if (state.checkpointRepair) return state.checkpointRepair;
    const records = await allDatasetRecords();
    const recoverable = records
      .map((record) => ({ record, kind: checkpointRecoveryKind(record) }))
      .filter((item) => item.kind);
    const counts = {
      v3_false_http_200: 0,
      legacy_http_429: 0,
      transient_network_or_json: 0,
    };
    for (const { record, kind } of recoverable) {
      counts[kind] += 1;
      await idbPut('records', recoverCheckpointRecord(record, kind));
    }
    if ((counts.legacy_http_429 || counts.transient_network_or_json) && !(await getActiveCooldown())) {
      const nowMs = Date.now();
      const consecutiveThrottles = counts.legacy_http_429 ? 4 : 0;
      const delayMs = computeThrottleCooldownMs(consecutiveThrottles, null, nowMs);
      await idbPut('meta', {
        key: cooldownKey(),
        datasetSha256: CONFIG.datasetSha256,
        status: 'active',
        kind: counts.legacy_http_429 ? 'recovered_legacy_http_429' : 'recovered_transient_network_or_json',
        reason: `${counts.legacy_http_429} throttle e ${counts.transient_network_or_json} falhas transitorias recuperados`,
        card_id: recoverable[0].record.card_id,
        batch: recoverable[0].record.batch,
        retry_after_observed: null,
        consecutive_throttles: consecutiveThrottles,
        created_at: new Date(nowMs).toISOString(),
        until_ms: nowMs + delayMs,
        until: new Date(nowMs + delayMs).toISOString(),
        delay_ms: delayMs,
      });
    }
    state.checkpointRepair = { ...counts, total: recoverable.length };
    if (recoverable.length) {
      console.warn(`Checkpoint reparado sem rede: ${counts.v3_false_http_200} falsos HTTP 200 da V3, ${counts.legacy_http_429} throttles e ${counts.transient_network_or_json} falhas transitorias voltaram para pending.`);
    }
    return state.checkpointRepair;
  }

  async function getCooldown(channel = 'data') {
    return idbGet('meta', cooldownKey(channel));
  }

  async function getActiveCooldown(nowMs = Date.now(), channel = 'data') {
    const cooldown = await getCooldown(channel);
    if (!cooldown?.until_ms || cooldown.until_ms <= nowMs) return null;
    return { ...cooldown, remaining_ms: cooldown.until_ms - nowMs };
  }

  async function registerCooldown({ cardId, batchNo, kind, retryAfterValue = null, reason, channel = 'data' }) {
    const nowMs = Date.now();
    const previous = await getCooldown(channel);
    const isThrottle = /(?:^|_)http_429$/.test(kind);
    const consecutiveThrottles = isThrottle
      ? (Number(previous?.consecutive_throttles) || 0) + 1
      : Number(previous?.consecutive_throttles) || 0;
    const delayMs = isThrottle
      ? buildThrottleDecision(consecutiveThrottles, retryAfterValue, nowMs).cooldown_ms
      : Math.max(CONFIG.throttleBaseMs, computeBackoffMs(1, retryAfterValue, nowMs));
    const cooldown = {
      key: cooldownKey(channel),
      datasetSha256: CONFIG.datasetSha256,
      status: 'active',
      kind, channel,
      reason,
      card_id: cardId,
      batch: batchNo,
      retry_after_observed: retryAfterValue,
      consecutive_throttles: consecutiveThrottles,
      created_at: new Date(nowMs).toISOString(),
      until_ms: nowMs + delayMs,
      until: new Date(nowMs + delayMs).toISOString(),
      delay_ms: delayMs,
    };
    await idbPut('meta', cooldown);
    return cooldown;
  }

  async function clearCooldownAfterResponse(channel = 'data') {
    const previous = await getCooldown(channel);
    if (!previous || (previous.status === 'clear' && !previous.consecutive_throttles)) return;
    await idbPut('meta', {
      ...previous,
      key: cooldownKey(channel),
      status: 'clear',
      consecutive_throttles: 0,
      cleared_at: new Date().toISOString(),
      until_ms: 0,
      until: null,
    });
  }

  async function markTransientPending(cardId, batchNo, previousRecord, attempts, details) {
    return idbPut('records', {
      ...(previousRecord ?? {}),
      key: recordKey(cardId),
      datasetSha256: CONFIG.datasetSha256,
      card_id: cardId,
      batch: batchNo,
      status: 'throttled_pending',
      attempts: 0,
      historical_attempts: (Number(previousRecord?.historical_attempts) || 0) + attempts,
      source_url: new URL(CONFIG.endpointPath(cardId), location.origin).href,
      updated_at: new Date().toISOString(),
      ...details,
    });
  }

  function decodeEmbeddedIdsText() {
    return atob(EMBEDDED_IDS_BASE64);
  }

  async function validateEmbeddedDataset() {
    const text = decodeEmbeddedIdsText();
    const hash = await sha256Text(text);
    if (hash !== CONFIG.datasetSha256) {
      throw new Error(`Lista embutida alterada. SHA-256 recebido: ${hash}; esperado: ${CONFIG.datasetSha256}.`);
    }
    const ids = text.split(/\r?\n/).map((id) => id.trim()).filter(Boolean);
    if (ids.length !== CONFIG.expectedMissing) {
      throw new Error(`Quantidade incorreta: ${ids.length}; esperado: ${CONFIG.expectedMissing}.`);
    }
    if (ids.some((id) => !/^\d+$/.test(id))) throw new Error('A lista contem card_id nao numerico.');
    if (new Set(ids).size !== ids.length) throw new Error('A lista contem card_id duplicado.');
    if (CONFIG.expectedMissing + CONFIG.alreadyCompleteExcluded !== CONFIG.impulseUniverse) {
      throw new Error('A particao embutida nao fecha o universo de cards com impeto.');
    }
    return { ids, text, hash };
  }

  async function installEmbeddedDataset() {
    const validated = await validateEmbeddedDataset();
    await idbPut('meta', {
      key: `dataset:${CONFIG.datasetSha256}`,
      schemaVersion: CONFIG.schemaVersion,
      ids: validated.ids,
      importedAt: new Date().toISOString(),
      sourceFileName: 'lista_embutida_no_coletor',
      sourceSha256: validated.hash,
      partition: {
        impulse_universe: CONFIG.impulseUniverse,
        already_complete_excluded: CONFIG.alreadyCompleteExcluded,
        expected_missing: CONFIG.expectedMissing,
      },
    });
    return validated.ids;
  }

  async function getDatasetIds() {
    const saved = await idbGet('meta', `dataset:${CONFIG.datasetSha256}`);
    if (saved?.ids?.length === CONFIG.expectedMissing) return saved.ids;
    return installEmbeddedDataset();
  }

  async function selecionarPastaDaColeta() {
    if (!('showDirectoryPicker' in globalThis)) {
      throw new Error('Este Chrome nao oferece selecao de DIRETORIO. Nenhuma rede foi iniciada. Atualize o Chrome e tente novamente.');
    }
    console.warn('SELETOR DE DIRETORIO: dentro de Downloads, escolha a pasta comum chamada coleta-efhub-dados-fotos. Nao escolha Downloads e nao escolha arquivo.');
    const handle = await globalThis.showDirectoryPicker({ id: 'clubeft7-collection-target', mode: 'readwrite', startIn: 'downloads' });
    if (String(handle.name).toLowerCase() !== 'coleta-efhub-dados-fotos') {
      throw new Error(`Pasta selecionada: ${handle.name}. Escolha Downloads/coleta-efhub-dados-fotos. Nenhuma rede foi iniciada.`);
    }
    let permission = await handle.queryPermission({ mode: 'readwrite' });
    if (permission !== 'granted') permission = await handle.requestPermission({ mode: 'readwrite' });
    if (permission !== 'granted') throw new Error('Permissao de escrita nao concedida. Nenhuma rede foi iniciada.');
    const run = {
      key: `run:${CONFIG.datasetSha256}`,
      schema_version: CONFIG.schemaVersion,
      folder_name: handle.name,
      created_at: new Date().toISOString(),
      restarted_from_zero_by_user_request: true,
      prior_checkpoint_used_as_progress: false,
      initial_pending: CONFIG.expectedMissing,
    };
    await idbPut('meta', { key: `output-folder:${CONFIG.datasetSha256}`, handle, folder_name: handle.name, saved_at: run.created_at });
    await idbPut('meta', run);
    return { handle, run };
  }

  async function getGrantedOutputRoot() {
    const saved = await idbGet('meta', `output-folder:${CONFIG.datasetSha256}`);
    const handle = saved?.handle;
    if (!handle) return null;
    try {
      return (await handle.queryPermission({ mode: 'readwrite' })) === 'granted' ? handle : null;
    } catch {
      return null;
    }
  }

  async function requireCollectionFolder() {
    const root = await getGrantedOutputRoot();
    if (!root) throw new Error('A pasta exclusiva da coleta nao esta autorizada. Nenhuma rede foi iniciada; execute iniciar().');
    return root;
  }

  async function getOptionalCategoryDirectory(batchNo, category) {
    const root = await getGrantedOutputRoot();
    if (!root) throw new Error('Pasta da coleta indisponivel. Nenhuma rede sera iniciada; execute iniciar() e escolha Downloads/coleta-efhub-dados-fotos.');
    try {
      const batchDir = await root.getDirectoryHandle(batchLabel(batchNo), { create: true });
      return batchDir.getDirectoryHandle(category, { create: true });
    } catch (error) {
      throw new Error(`Nao foi possivel gravar na pasta exclusiva: ${error.message}. Nao havera fallback para Downloads.`);
    }
  }

  function batchLabel(batchNo) {
    return `LOTE-${String(batchNo).padStart(4, '0')}-DE-${String(CONFIG.totalBatches).padStart(4, '0')}`;
  }

  async function writeBlobArtifact(batchNo, category, fileName, blob) {
    const directory = await getOptionalCategoryDirectory(batchNo, category);
    const fileHandle = await directory.getFileHandle(fileName, { create: true });
    const writable = await fileHandle.createWritable();
    await writable.write(blob);
    await writable.close();
    const root = await idbGet('meta', `output-folder:${CONFIG.datasetSha256}`);
    return { mode: 'exclusive_directory', name: `${root.folder_name}/${batchLabel(batchNo)}/${category}/${fileName}` };
  }

  async function writeArtifact(batchNo, fileName, text) {
    return writeBlobArtifact(batchNo, 'dados', fileName, new Blob([text], { type: 'text/plain;charset=utf-8' }));
  }

  function ensureOverlay() {
    if (state.overlay?.host?.isConnected) return state.overlay;
    const host = document.createElement('div');
    host.id = 'clubeft7-progress';
    host.style.cssText = 'position:fixed;right:16px;bottom:16px;z-index:2147483647';
    const shadow = host.attachShadow({ mode: 'open' });
    shadow.innerHTML = `
      <style>
        .box{width:360px;background:#111827;color:#f9fafb;border:1px solid #374151;border-radius:12px;padding:14px;font:13px/1.45 system-ui;box-shadow:0 12px 36px #0008}
        .title{font-weight:800;margin-bottom:8px}.status{color:#93c5fd;white-space:pre-wrap}.bar{height:8px;background:#374151;border-radius:999px;overflow:hidden;margin:10px 0}.fill{height:100%;width:0;background:#22c55e;transition:width .2s}.counts{font-variant-numeric:tabular-nums}.actions{display:flex;gap:8px;margin-top:10px}button{border:0;border-radius:8px;padding:7px 10px;cursor:pointer}button:first-child{background:#f59e0b;color:#111827}button:last-child{background:#334155;color:white}
      </style>
      <div class="box">
        <div class="title">Tarefa 7 · eFootballHub</div>
        <div class="status">Pronto.</div>
        <div class="bar"><div class="fill"></div></div>
        <div class="counts">Aguardando lote.</div>
        <div class="actions"><button class="pause">Pausar com seguranca</button><button class="export">Exportar checkpoint</button></div>
      </div>`;
    document.body.appendChild(host);
    const overlay = {
      host,
      status: shadow.querySelector('.status'),
      fill: shadow.querySelector('.fill'),
      counts: shadow.querySelector('.counts'),
    };
    shadow.querySelector('.pause').onclick = () => pausar();
    shadow.querySelector('.export').onclick = () => state.currentBatch ? exportar(state.currentBatch) : console.warn('Nenhum lote ativo.');
    state.overlay = overlay;
    return overlay;
  }

  function updateOverlay({ status, done = 0, total = 1, counts = '', current = '' }) {
    const overlay = ensureOverlay();
    overlay.status.textContent = `${status}${current ? `\ncard_id: ${current}` : ''}`;
    overlay.fill.style.width = `${Math.max(0, Math.min(100, (done / Math.max(total, 1)) * 100))}%`;
    overlay.counts.textContent = counts;
  }

  async function pace() {
    const activeCooldown = await getActiveCooldown();
    if (activeCooldown) {
      throw new BatchStopError(`Cooldown ativo ate ${activeCooldown.until}; aguarde ${Math.ceil(activeCooldown.remaining_ms / 1000)} s antes de retomar.`);
    }
    const persistedRate = await idbGet('meta', rateKey());
    const notBefore = Math.max(
      Number(persistedRate?.next_request_not_before_ms) || 0,
      Number(state.lastRequestStartedAt) + CONFIG.minIntervalMs,
    );
    const waitMs = notBefore - Date.now();
    if (waitMs > 0) await sleep(waitMs);
    const startedAt = Date.now();
    const intervalMs = CONFIG.minIntervalMs + Math.floor(CONFIG.intervalJitterMs * randomFraction());
    state.lastRequestStartedAt = startedAt;
    await idbPut('meta', {
      key: rateKey(),
      datasetSha256: CONFIG.datasetSha256,
      last_request_started_at: new Date(startedAt).toISOString(),
      next_request_not_before_ms: startedAt + intervalMs,
      next_request_not_before: new Date(startedAt + intervalMs).toISOString(),
      interval_ms: intervalMs,
    });
  }

  async function paceImage() {
    const activeCooldown = await getActiveCooldown(Date.now(), 'photo');
    if (activeCooldown) {
      throw new BatchStopError(`Cooldown ativo ate ${activeCooldown.until}; foto permanece pendente.`);
    }
    const rate = await idbGet('meta', imageRateKey());
    const waitMs = (Number(rate?.next_request_not_before_ms) || 0) - Date.now();
    if (waitMs > 0) await sleep(waitMs);
    const startedAt = Date.now();
    const intervalMs = CONFIG.imageMinIntervalMs + Math.floor(CONFIG.imageIntervalJitterMs * randomFraction());
    await idbPut('meta', {
      key: imageRateKey(), datasetSha256: CONFIG.datasetSha256,
      last_request_started_at: new Date(startedAt).toISOString(),
      next_request_not_before_ms: startedAt + intervalMs,
      next_request_not_before: new Date(startedAt + intervalMs).toISOString(),
      interval_ms: intervalMs,
    });
  }

  async function fetchWithTimeout(url) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort('request_timeout'), CONFIG.requestTimeoutMs);
    try {
      return await fetch(url, {
        method: 'GET',
        credentials: 'include',
        headers: { Accept: 'application/json' },
        signal: controller.signal,
        cache: 'no-store',
      });
    } finally {
      clearTimeout(timer);
    }
  }

  async function fetchImageWithTimeout(url) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort('image_request_timeout'), CONFIG.imageRequestTimeoutMs);
    try {
      return await fetch(url, {
        method: 'GET', credentials: 'omit', mode: 'cors', cache: 'no-store',
        headers: { Accept: 'image/*' }, signal: controller.signal,
      });
    } finally {
      clearTimeout(timer);
    }
  }

  async function persistAttempt(cardId, batchNo, attempts, extra = {}) {
    return idbPut('records', {
      key: recordKey(cardId),
      datasetSha256: CONFIG.datasetSha256,
      card_id: cardId,
      batch: batchNo,
      status: 'in_progress',
      attempts,
      source_url: new URL(CONFIG.endpointPath(cardId), location.origin).href,
      updated_at: new Date().toISOString(),
      ...extra,
    });
  }

  async function collectCard(cardId, batchNo, previousRecord, { probe = false } = {}) {
    let attempts = Math.max(0, Number(previousRecord?.attempts) || 0);
    const attemptLimit = probe ? attempts + 1 : CONFIG.maxAttempts;
    const sourceUrl = new URL(CONFIG.endpointPath(cardId), location.origin).href;
    let lastError = previousRecord?.last_error ?? null;

    while (attempts < attemptLimit) {
      if (state.paused) throw new BatchStopError('Pausa solicitada pelo usuario.');
      attempts += 1;
      await persistAttempt(cardId, batchNo, attempts, { last_error: lastError, probe });
      await pace();
      let response;
      try {
        response = await fetchWithTimeout(sourceUrl);
      } catch (error) {
        lastError = `network:${error.name}:${error.message}`;
        await persistAttempt(cardId, batchNo, attempts, { last_error: lastError, probe });
        if (probe) {
          const cooldown = await registerCooldown({ cardId, batchNo, kind: 'probe_network', reason: lastError });
          await markTransientPending(cardId, batchNo, previousRecord, attempts, {
            status: 'transient_pending', reason: 'probe_transient_network', last_error: lastError, cooldown_until: cooldown.until,
          });
          throw new BatchStopError(`Sonda sem resposta; ID preservado em pending. Cooldown ate ${cooldown.until}.`);
        }
        if (attempts < attemptLimit) {
          await sleep(computeBackoffMs(attempts));
          continue;
        }
        const cooldown = await registerCooldown({ cardId, batchNo, kind: 'network', reason: lastError });
        await markTransientPending(cardId, batchNo, previousRecord, attempts, {
          status: 'transient_pending', reason: 'transient_network_after_retries', last_error: lastError,
          cooldown_until: cooldown.until, terminal_failure: false,
        });
        throw new BatchStopError(`Rede indisponivel para ${cardId}; ID continua pending e cooldown foi gravado ate ${cooldown.until}.`);
      }

      const httpClass = classifyHttp(response.status);
      if (httpClass === 'throttle') {
        const retryAfterValue = response.headers.get('retry-after');
        const cooldown = await registerCooldown({
          cardId, batchNo, kind: 'http_429', retryAfterValue, reason: `HTTP 429${probe ? ' na sonda' : ''}`,
        });
        await markTransientPending(cardId, batchNo, previousRecord, attempts, {
          reason: 'transient_http_429',
          last_error: 'HTTP 429 Too Many Requests',
          http_status: 429,
          retry_after_observed: retryAfterValue,
          cooldown_until: cooldown.until,
        });
        throw new BatchStopError(`HTTP 429; ID preservado em pending. Retry-After respeitado e cooldown gravado ate ${cooldown.until}.`);
      }
      if (httpClass === 'stop_batch') {
        await persistAttempt(cardId, batchNo, attempts, { last_error: `HTTP ${response.status}; lote interrompido sem consumir o ID.`, probe });
        throw new BatchStopError(`HTTP ${response.status}. Confirme que a aba esta em efhub.com e retome depois.`);
      }
      if (httpClass === 'inactive_excluded') {
        await clearCooldownAfterResponse();
        return {
          status: 'inactive_excluded', attempts, source_url: sourceUrl,
          reason: `HTTP ${response.status}`, http_status: response.status,
        };
      }
      if (httpClass === 'retry') {
        const retryAfterValue = response.headers.get('retry-after');
        lastError = `HTTP ${response.status}`;
        await persistAttempt(cardId, batchNo, attempts, {
          last_error: lastError, http_status: response.status, retry_after_observed: retryAfterValue, probe,
        });
        if (probe) {
          const cooldown = await registerCooldown({
            cardId, batchNo, kind: `probe_http_${response.status}`, retryAfterValue, reason: lastError,
          });
          await markTransientPending(cardId, batchNo, previousRecord, attempts, {
            status: 'transient_pending', reason: 'probe_transient_http', last_error: lastError, http_status: response.status,
            retry_after_observed: retryAfterValue, cooldown_until: cooldown.until,
          });
          throw new BatchStopError(`Sonda recebeu HTTP ${response.status}; ID preservado em pending. Cooldown ate ${cooldown.until}.`);
        }
        if (attempts < attemptLimit) {
          await sleep(computeBackoffMs(attempts, retryAfterValue));
          continue;
        }
        const cooldown = await registerCooldown({
          cardId, batchNo, kind: `transient_http_${response.status}`, retryAfterValue, reason: lastError,
        });
        await markTransientPending(cardId, batchNo, previousRecord, attempts, {
          status: 'transient_pending', reason: 'transient_http_after_retries', last_error: lastError,
          http_status: response.status, retry_after_observed: retryAfterValue,
          cooldown_until: cooldown.until, terminal_failure: false,
        });
        throw new BatchStopError(`HTTP ${response.status} permaneceu transitorio; ID ${cardId} continua pending.`);
      }
      if (httpClass === 'failed') {
        await clearCooldownAfterResponse();
        return {
          status: 'failed', attempts, source_url: sourceUrl,
          reason: `HTTP ${response.status}`, http_status: response.status,
        };
      }

      let raw;
      try {
        raw = await response.json();
      } catch (error) {
        lastError = `invalid_json:${error.message}`;
        await persistAttempt(cardId, batchNo, attempts, { last_error: lastError, http_status: response.status, probe });
        if (attempts < attemptLimit) {
          await sleep(computeBackoffMs(attempts));
          continue;
        }
        const cooldown = await registerCooldown({ cardId, batchNo, kind: 'invalid_json', reason: lastError });
        await markTransientPending(cardId, batchNo, previousRecord, attempts, {
          status: 'transient_pending', reason: 'invalid_json_after_retries', last_error: lastError,
          http_status: response.status, cooldown_until: cooldown.until, terminal_failure: false,
        });
        throw new BatchStopError(`Resposta 2xx sem JSON utilizavel para ${cardId}; ID continua pending para diagnostico.`);
      }

      await clearCooldownAfterResponse();
      const validation = validatePayload(cardId, raw);
      if (!validation.ok) {
        if (validation.classification !== 'ambiguous_excluded') {
          await markTransientPending(cardId, batchNo, previousRecord, attempts, {
            status: 'schema_pending', reason: 'schema_validation_pending',
            last_error: validation.reason, http_status: response.status,
            validation_details: validation.details ?? null,
            requested_card_id: cardId, observed_id: validation.observed_id ?? null,
            observed_top_level_keys: raw && typeof raw === 'object' ? Object.keys(raw).sort() : [],
            raw_response_sha256: await sha256Text(stableStringify(raw)),
            terminal_failure: false,
          });
          throw new BatchStopError(`JSON 2xx de ${cardId} nao correspondeu ao contrato; ID ficou schema_pending e o lote foi interrompido para diagnostico.`);
        }
        return {
          status: validation.classification, attempts, source_url: sourceUrl,
          reason: validation.reason, validation_details: validation.details ?? null,
          requested_card_id: cardId, observed_id: validation.observed_id ?? null,
          raw_response_sha256: await sha256Text(stableStringify(raw)),
        };
      }

      const canonicalPayload = stableStringify(validation.payload);
      const structuredPayload = structuredPayloadWithoutEfootballDbOwnedFields(validation.payload);
      const canonicalStructuredPayload = stableStringify(structuredPayload);
      return {
        status: 'collected',
        attempts,
        result: {
          schema_version: 't7-efhub-card-v1',
          card_id: cardId,
          source_url: sourceUrl,
          source_page_origin: location.origin,
          fetched_at: new Date().toISOString(),
          response_sha256: await sha256Text(canonicalPayload),
          structured_payload_sha256: await sha256Text(canonicalStructuredPayload),
          excluded_source_owned_fields: ['boostId', 'boostId2', 'booster*', 'box*', 'pack*'],
          source_ownership_note: 'impetos_boosters_boxes_permanecem_efootballdb',
          cloudinary_url: null,
          efhub_source_url: validation.photo.sourceUrl,
          image_observed_url: validation.photo.observedUrl,
          image_validation_status: validation.photo.status,
          image_priority_contract: ['cloudinary_url', 'efhub_source_url'],
          payload: structuredPayload,
        },
      };
    }

    const cooldown = await registerCooldown({ cardId, batchNo, kind: 'retry_state', reason: lastError ?? 'attempt_limit_reached' });
    await markTransientPending(cardId, batchNo, previousRecord, attempts, {
      status: 'transient_pending', reason: 'attempt_limit_reached_nonterminal', last_error: lastError,
      cooldown_until: cooldown.until, terminal_failure: false,
    });
    throw new BatchStopError(`Limite transitorio atingido para ${cardId}; ID preservado em pending.`);
  }

  async function saveTerminalRecord(cardId, batchNo, outcome) {
    const record = {
      key: recordKey(cardId),
      datasetSha256: CONFIG.datasetSha256,
      card_id: cardId,
      batch: batchNo,
      updated_at: new Date().toISOString(),
      ...outcome,
    };
    await idbPut('records', record);
    return record;
  }

  async function saveDataOutcomeWithPhotoCheckpoint(cardId, batchNo, outcome) {
    if (outcome.status !== 'collected') return saveTerminalRecord(cardId, batchNo, outcome);
    const hasPhoto = Boolean(outcome.result?.efhub_source_url);
    return saveTerminalRecord(cardId, batchNo, {
      ...outcome,
      status: hasPhoto ? 'photo_pending' : 'collected',
      result: {
        ...outcome.result,
        photo_download: hasPhoto
          ? { status: 'pending', source_url: outcome.result.efhub_source_url }
          : { status: 'unavailable', reason: outcome.result?.image_validation_status ?? 'missing' },
      },
    });
  }

  async function migratePriorCollectedToPhotoPending() {
    if (state.migratedPhotoState) return 0;
    const records = await allDatasetRecords();
    const candidates = records.filter((record) => record.status === 'collected'
      && record.result?.efhub_source_url
      && !['downloaded', 'download_triggered_unverified', 'unavailable'].includes(record.result?.photo_download?.status));
    for (const record of candidates) {
      await idbPut('records', {
        ...record,
        status: 'photo_pending',
        updated_at: new Date().toISOString(),
        result: {
          ...record.result,
          photo_download: { status: 'pending', source_url: record.result.efhub_source_url, migrated_from_data_only: true },
        },
      });
    }
    state.migratedPhotoState = true;
    if (candidates.length) console.info(`${candidates.length} cards com dados ja salvos foram movidos para photo_pending sem refazer a API.`);
    return candidates.length;
  }

  async function downloadPhotoForRecord(record) {
    const cardId = record.card_id;
    const batchNo = record.batch;
    const sourceUrl = record.result?.efhub_source_url;
    const photoValidation = validatePhoto(cardId, sourceUrl);
    if (!photoValidation.sourceUrl) {
      return saveTerminalRecord(cardId, batchNo, {
        ...record,
        status: 'collected',
        result: { ...record.result, photo_download: { status: 'unavailable', reason: photoValidation.status } },
      });
    }

    await paceImage();
    let response;
    try {
      response = await fetchImageWithTimeout(sourceUrl);
    } catch (error) {
      await idbPut('records', {
        ...record, status: 'photo_pending', updated_at: new Date().toISOString(),
        result: {
          ...record.result,
          photo_download: { status: 'pending', source_url: sourceUrl, reason: `cors_or_network:${error.name}:${error.message}` },
        },
      });
      throw new BatchStopError(`Foto de ${cardId} permaneceu pending; nenhum arquivo solto foi baixado.`);
    }

    const imageHttpClass = classifyImageHttp(response.status);
    if (imageHttpClass === 'throttle_pending') {
      const retryAfterValue = response.headers.get('retry-after');
      const cooldown = await registerCooldown({
        cardId, batchNo, kind: 'image_http_429', retryAfterValue, reason: 'HTTP 429 no download da foto', channel: 'photo',
      });
      await idbPut('records', {
        ...record, status: 'photo_pending', updated_at: new Date().toISOString(),
        result: {
          ...record.result,
          photo_download: { status: 'pending', source_url: sourceUrl, reason: 'HTTP 429', cooldown_until: cooldown.until },
        },
      });
      throw new BatchStopError(`HTTP 429 na foto de ${cardId}; dados preservados e foto pending ate ${cooldown.until}.`);
    }

    await clearCooldownAfterResponse('photo');

    if (imageHttpClass === 'unavailable') {
      return saveTerminalRecord(cardId, batchNo, {
        ...record,
        status: 'collected',
        result: { ...record.result, photo_download: { status: 'unavailable', source_url: sourceUrl, http_status: response.status } },
      });
    }

    if (imageHttpClass === 'retry_pending') {
      const retryAfterValue = response.headers.get('retry-after');
      const cooldown = await registerCooldown({
        cardId, batchNo, kind: `image_http_${response.status}`, retryAfterValue, reason: `HTTP ${response.status} na foto`, channel: 'photo',
      });
      await idbPut('records', {
        ...record, status: 'photo_pending', updated_at: new Date().toISOString(),
        result: {
          ...record.result,
          photo_download: { status: 'pending', source_url: sourceUrl, reason: `HTTP ${response.status}`, cooldown_until: cooldown.until },
        },
      });
      throw new BatchStopError(`Foto de ${cardId} recebeu HTTP ${response.status}; dados preservados e foto pending.`);
    }

    const contentType = response.headers.get('content-type') || 'application/octet-stream';
    const blob = await response.blob();
    if (!contentType.toLowerCase().startsWith('image/') || blob.size === 0) {
      await idbPut('records', {
        ...record, status: 'photo_pending', updated_at: new Date().toISOString(),
        result: {
          ...record.result,
          photo_download: { status: 'pending', source_url: sourceUrl, reason: 'invalid_or_empty_image_response' },
        },
      });
      throw new BatchStopError(`Foto invalida para ${cardId}; permaneceu pending e nenhum fallback foi baixado.`);
    }

    const bytes = await blob.arrayBuffer();
    const artifact = await writeBlobArtifact(batchNo, 'imagens', photoFileName(cardId), blob);
    return saveTerminalRecord(cardId, batchNo, {
      ...record,
      status: 'collected',
      result: {
        ...record.result,
        photo_download: {
          status: 'downloaded', source_url: sourceUrl, file_name: photoFileName(cardId),
          content_type: contentType, size_bytes: blob.size, sha256: await sha256Bytes(bytes), ...artifact,
        },
      },
    });
  }

  function statusCounts(ids, records) {
    const byId = new Map(records.map((record) => [record.card_id, record]));
    const lists = {
      expected: [...ids], collected: [], failed: [], pending: [],
      ambiguous_excluded: [], inactive_excluded: [],
    };
    for (const id of ids) {
      const status = byId.get(id)?.status;
      if (status === 'collected') lists.collected.push(id);
      else if (status === 'failed') lists.failed.push(id);
      else if (status === 'ambiguous_excluded') lists.ambiguous_excluded.push(id);
      else if (status === 'inactive_excluded') lists.inactive_excluded.push(id);
      else lists.pending.push(id);
    }
    return lists;
  }

  function dataIsComplete(record) {
    return Boolean(record?.result?.payload)
      || ['failed', 'ambiguous_excluded', 'inactive_excluded'].includes(record?.status);
  }

  function photoIsPending(record) {
    return Boolean(record?.result?.payload) && record?.result?.photo_download?.status === 'pending';
  }

  function phaseCounts(ids, records) {
    const byId = new Map(records.map((record) => [record.card_id, record]));
    const selected = ids.map((id) => byId.get(id)).filter(Boolean);
    return {
      data_saved: selected.filter((record) => record.result?.payload).length,
      data_pending: ids.filter((id) => !dataIsComplete(byId.get(id))).length,
      photos_done: selected.filter((record) => ['downloaded', 'unavailable'].includes(record.result?.photo_download?.status)).length,
      photos_pending: selected.filter(photoIsPending).length,
    };
  }

  async function firstPendingDataBatch(ids) {
    const records = await allDatasetRecords();
    const byId = new Map(records.map((record) => [record.card_id, record]));
    for (let index = 0; index < ids.length; index += 1) {
      if (!dataIsComplete(byId.get(ids[index]))) return batchForIndex(index);
    }
    return null;
  }

  async function firstPendingPhotoBatch(ids) {
    const records = await allDatasetRecords();
    const byId = new Map(records.map((record) => [record.card_id, record]));
    for (let index = 0; index < ids.length; index += 1) {
      if (photoIsPending(byId.get(ids[index]))) return batchForIndex(index);
    }
    return null;
  }

  function jsonl(items) {
    return items.length ? `${items.map((item) => JSON.stringify(item)).join('\n')}\n` : '';
  }

  function txt(items) {
    return items.length ? `${items.join('\n')}\n` : '';
  }

  async function exportar(batchNo = state.currentBatch) {
    await repairCheckpointFailures();
    await migratePriorCollectedToPhotoPending();
    const ids = await getDatasetIds();
    const batchIds = idsForBatch(ids, batchNo);
    const allRecords = await allDatasetRecords();
    const recordMap = new Map(allRecords.map((record) => [record.card_id, record]));
    const batchRecords = batchIds.map((id) => recordMap.get(id)).filter(Boolean);
    const batchLists = statusCounts(batchIds, batchRecords);
    const overallLists = statusCounts(ids, allRecords);
    const structuredDataRecords = batchRecords.map((record) => record.result).filter((result) => result?.payload);
    const photoRecords = batchRecords
      .filter((record) => record.result?.photo_download)
      .map((record) => ({
        card_id: record.card_id,
        source_url: record.result.efhub_source_url ?? null,
        photo_download: record.result.photo_download,
      }));
    const photoCounts = {
      downloaded: photoRecords.filter((record) => record.photo_download.status === 'downloaded').length,
      download_triggered_unverified: photoRecords.filter((record) => record.photo_download.status === 'download_triggered_unverified').length,
      unavailable: photoRecords.filter((record) => record.photo_download.status === 'unavailable').length,
      pending: photoRecords.filter((record) => record.photo_download.status === 'pending').length,
    };
    const failedRecords = batchLists.failed.map((id) => recordMap.get(id)).filter(Boolean);
    const excludedRecords = [...batchLists.ambiguous_excluded, ...batchLists.inactive_excluded]
      .map((id) => recordMap.get(id)).filter(Boolean);
    const lastTerminalRecord = batchRecords
      .filter((record) => ['collected', 'failed', 'ambiguous_excluded', 'inactive_excluded'].includes(record.status))
      .at(-1) ?? null;
    const nextPendingCardId = batchLists.pending[0] ?? null;
    const cooldown = await getCooldown();
    const photoCooldown = await getCooldown('photo');
    const run = await idbGet('meta', `run:${CONFIG.datasetSha256}`);

    const checkpoint = {
      schema_version: CONFIG.schemaVersion,
      dataset_sha256: CONFIG.datasetSha256,
      batch: batchNo,
      batch_label: batchLabel(batchNo),
      exported_at: new Date().toISOString(),
      resume_one_line: 'await ClubEFT7.retomar()',
      last_terminal_card_id: lastTerminalRecord?.card_id ?? null,
      last_terminal_source_url: lastTerminalRecord?.source_url ?? lastTerminalRecord?.result?.source_url ?? null,
      next_pending_card_id: nextPendingCardId,
      next_pending_source_url: nextPendingCardId ? `${CONFIG.requiredOrigin}${CONFIG.endpointPath(nextPendingCardId)}` : null,
      batch_counts: {
        expected: batchLists.expected.length,
        collected: batchLists.collected.length,
        failed: batchLists.failed.length,
        pending: batchLists.pending.length,
        ambiguous_excluded: batchLists.ambiguous_excluded.length,
        inactive_excluded: batchLists.inactive_excluded.length,
        data_payloads_saved: structuredDataRecords.length,
        photos: photoCounts,
      },
      cooldown,
      checkpoint_repair: state.checkpointRepair,
      checkpoint_storage: 'IndexedDB do perfil atual do navegador',
      output_folder: run?.folder_name ?? null,
      restarted_from_zero_by_user_request: run?.restarted_from_zero_by_user_request === true,
      prior_checkpoint_used_as_progress: false,
      phase_counts: {
        data_saved: structuredDataRecords.length,
        photos_completed: photoCounts.downloaded + photoCounts.unavailable,
        photos_pending: photoCounts.pending,
      },
    };

    const files = {
      '01-expected.txt': txt(batchLists.expected),
      '02-collected.txt': txt(batchLists.collected),
      '03-failed.txt': txt(batchLists.failed),
      '04-pending.txt': txt(batchLists.pending),
      '05-dados-estruturados.jsonl': jsonl(structuredDataRecords),
      '06-manifesto-fotos.jsonl': jsonl(photoRecords),
      '07-falhas.jsonl': jsonl(failedRecords),
      '08-excluidos.jsonl': jsonl(excludedRecords),
      '09-checkpoint.json': `${JSON.stringify(checkpoint, null, 2)}\n`,
    };

    const artifactHashes = {};
    for (const [name, content] of Object.entries(files)) artifactHashes[name] = await sha256Text(content);

    const finalState = {
      schema_version: CONFIG.schemaVersion,
      generated_at: new Date().toISOString(),
      dataset: {
        source_file: CONFIG.datasetFile,
        source_sha256: CONFIG.datasetSha256,
        matching_key: 'original_konami_card_id',
        endpoint_template: `${CONFIG.requiredOrigin}/api/public/players/{card_id}`,
        batch_size_max: CONFIG.batchSize,
        total_batches: CONFIG.totalBatches,
      },
      manifest: {
        expected_missing: CONFIG.expectedMissing,
        already_complete_excluded: CONFIG.alreadyCompleteExcluded,
        collected: overallLists.collected.length,
        failed: overallLists.failed.length,
        pending: overallLists.pending.length,
        ambiguous_excluded: overallLists.ambiguous_excluded.length,
        inactive_excluded: overallLists.inactive_excluded.length,
        data_payloads_saved: allRecords.filter((record) => record.result?.payload).length,
        photos_downloaded: allRecords.filter((record) => record.result?.photo_download?.status === 'downloaded').length,
        photos_download_triggered_unverified: allRecords.filter((record) => record.result?.photo_download?.status === 'download_triggered_unverified').length,
        photos_unavailable: allRecords.filter((record) => record.result?.photo_download?.status === 'unavailable').length,
        photos_pending: allRecords.filter((record) => record.result?.photo_download?.status === 'pending').length,
      },
      run,
      batch: {
        number: batchNo,
        label: batchLabel(batchNo),
        expected: batchLists.expected.length,
        collected: batchLists.collected.length,
        failed: batchLists.failed.length,
        pending: batchLists.pending.length,
        ambiguous_excluded: batchLists.ambiguous_excluded.length,
        inactive_excluded: batchLists.inactive_excluded.length,
        data_payloads_saved: structuredDataRecords.length,
        photos: photoCounts,
        ids: batchLists,
      },
      artifacts_sha256: artifactHashes,
      checkpoint,
      protections: {
        reprocess_collected: false,
        supabase_write: false,
        cloudinary_upload: false,
        image_as_attribute_source: false,
        throttle_is_terminal_failure: false,
        efdb_impulse_box_overwrite: false,
        exact_card_id_photo_binding: true,
        image_download: true,
        http_2xx_parsed_before_terminal_classification: true,
        network_failure_is_terminal: false,
        schema_mismatch_stops_batch: true,
      },
      source_ownership: {
        structured_attributes: 'eFootballHub JSON API',
        impulses_boosters_boxes: 'eFootballDB preservado; campos boost*, booster*, box* e pack* excluidos do payload de saida',
        photo: 'eFootballHub URL validada pelo mesmo card_id',
      },
      rate_limiter: {
        serial: true,
        probe_first: true,
        min_interval_ms: CONFIG.minIntervalMs,
        interval_jitter_ms: CONFIG.intervalJitterMs,
        retry_after_respected: true,
        cooldown_persistent: true,
        cooldown,
        photo_cooldown: photoCooldown,
        image_serial: true,
        image_min_interval_ms: CONFIG.imageMinIntervalMs,
        image_interval_jitter_ms: CONFIG.imageIntervalJitterMs,
      },
    };
    files['10-estado-final.json'] = `${JSON.stringify(finalState, null, 2)}\n`;

    const outputs = [];
    for (const [name, content] of Object.entries(files)) outputs.push(await writeArtifact(batchNo, name, content));
    console.table(finalState.manifest);
    console.info(`Lote exportado. Retomada em uma linha: ${checkpoint.resume_one_line}`);
    return { finalState, outputs };
  }

  async function runDataBatch(batchNo) {
    if (state.running) throw new Error('Ja existe um lote em execucao nesta aba.');
    if (location.origin !== CONFIG.requiredOrigin) {
      throw new Error(`Abra ${CONFIG.requiredOrigin}/pt-BR/players antes de executar. Origem atual: ${location.origin}`);
    }
    await requireCollectionFolder();
    await repairCheckpointFailures();
    await migratePriorCollectedToPhotoPending();
    const ids = await getDatasetIds();
    const batchIds = idsForBatch(ids, batchNo);
    state.running = true;
    state.paused = false;
    state.currentBatch = batchNo;
    const startedAt = Date.now();
    const batchIdSet = new Set(batchIds);
    const batchRecordMap = new Map(
      (await allDatasetRecords())
        .filter((record) => batchIdSet.has(record.card_id))
        .map((record) => [record.card_id, record]),
    );

    try {
      const activeCooldown = await getActiveCooldown();
      if (activeCooldown) {
        throw new BatchStopError(`Cooldown persistente ativo ate ${activeCooldown.until}; nenhuma sonda foi enviada. Aguarde ${Math.ceil(activeCooldown.remaining_ms / 1000)} s.`);
      }

      const probeId = batchIds.find((cardId) => {
        return !dataIsComplete(batchRecordMap.get(cardId));
      });
      if (probeId) {
        const previousProbe = batchRecordMap.get(probeId) ?? null;
        updateOverlay({
          status: `${batchLabel(batchNo)} · FASE DADOS · sonda unica`,
          done: 0, total: batchIds.length, current: probeId,
          counts: 'Somente uma chamada sera feita; HTTP 429 encerra sem falhar o ID.',
        });
        const savedProbe = await saveDataOutcomeWithPhotoCheckpoint(
          probeId,
          batchNo,
          await collectCard(probeId, batchNo, previousProbe, { probe: true }),
        );
        batchRecordMap.set(probeId, savedProbe);
        updateOverlay({
          status: `${batchLabel(batchNo)} · sonda respondeu sem throttle; pausa conservadora`,
          done: 1, total: batchIds.length, current: probeId,
          counts: `Aguardando ${Math.ceil(CONFIG.probeSuccessPauseMs / 1000)} s antes da sequencia serial.`,
        });
        await sleep(CONFIG.probeSuccessPauseMs);
      }

      for (let i = 0; i < batchIds.length; i += 1) {
        const cardId = batchIds[i];
        const previous = batchRecordMap.get(cardId) ?? null;
        if (dataIsComplete(previous)) {
          const counts = phaseCounts(batchIds, [...batchRecordMap.values()]);
          updateOverlay({
            status: `${batchLabel(batchNo)} · ja registrado, sem reprocessar`,
            done: i + 1, total: batchIds.length, current: cardId,
            counts: `dados salvos ${counts.data_saved} · dados pendentes ${counts.data_pending} · fotos pendentes ${counts.photos_pending}`,
          });
          continue;
        }
        if (state.paused) throw new BatchStopError('Pausa solicitada pelo usuario.');

        const outcome = await collectCard(cardId, batchNo, previous);
        const savedRecord = await saveDataOutcomeWithPhotoCheckpoint(cardId, batchNo, outcome);
        batchRecordMap.set(cardId, savedRecord);
        const counts = phaseCounts(batchIds, [...batchRecordMap.values()]);
        const elapsed = Date.now() - startedAt;
        const rate = (i + 1) / Math.max(elapsed, 1);
        const etaMin = Math.max(0, ((batchIds.length - i - 1) / Math.max(rate, 0.000001)) / 60000);
        updateOverlay({
          status: `${batchLabel(batchNo)} · em andamento · ETA ${etaMin.toFixed(1)} min`,
          done: i + 1, total: batchIds.length, current: cardId,
          counts: `dados salvos ${counts.data_saved} · dados pendentes ${counts.data_pending} · fotos pendentes ${counts.photos_pending}`,
        });
      }
      updateOverlay({ status: `${batchLabel(batchNo)} concluido; exportando.`, done: batchIds.length, total: batchIds.length });
      return await exportar(batchNo);
    } catch (error) {
      if (error instanceof BatchStopError) {
        updateOverlay({ status: `${batchLabel(batchNo)} pausado com checkpoint persistente.\n${error.message}`, done: 0, total: 1 });
        await exportar(batchNo);
        console.warn(`${error.message} Retome em uma linha: await ClubEFT7.retomar()`);
        return { paused: true, reason: error.message };
      }
      throw error;
    } finally {
      state.running = false;
    }
  }

  async function runPhotoBatch(batchNo) {
    if (state.running) throw new Error('Ja existe um lote em execucao nesta aba.');
    if (location.origin !== CONFIG.requiredOrigin) throw new Error(`Abra ${CONFIG.requiredOrigin}/pt-BR/players antes de executar.`);
    await requireCollectionFolder();
    const ids = await getDatasetIds();
    const batchIds = idsForBatch(ids, batchNo);
    const batchSet = new Set(batchIds);
    const recordMap = new Map((await allDatasetRecords()).filter((r) => batchSet.has(r.card_id)).map((r) => [r.card_id, r]));
    state.running = true;
    state.paused = false;
    state.currentBatch = batchNo;
    try {
      const activeCooldown = await getActiveCooldown(Date.now(), 'photo');
      if (activeCooldown) throw new BatchStopError(`Cooldown de fotos ativo ate ${activeCooldown.until}; dados nao sao afetados.`);
      for (let i = 0; i < batchIds.length; i += 1) {
        const cardId = batchIds[i];
        const record = recordMap.get(cardId);
        if (!photoIsPending(record)) continue;
        if (state.paused) throw new BatchStopError('Pausa solicitada pelo usuario.');
        updateOverlay({
          status: `${batchLabel(batchNo)} · FASE FOTOS`, done: i + 1, total: batchIds.length, current: cardId,
          counts: 'Somente fotos pendentes; nenhum detalhe sera consultado.',
        });
        recordMap.set(cardId, await downloadPhotoForRecord(record));
      }
      return await exportar(batchNo);
    } catch (error) {
      if (error instanceof BatchStopError) {
        await exportar(batchNo);
        console.warn(`${error.message} Retome em uma linha: await ClubEFT7.retomar()`);
        return { paused: true, phase: 'photos', reason: error.message };
      }
      throw error;
    } finally {
      state.running = false;
    }
  }

  async function iniciar() {
    if (location.origin !== CONFIG.requiredOrigin) {
      throw new Error(`Abra ${CONFIG.requiredOrigin}/pt-BR/players e cole o script novamente.`);
    }
    ensureOverlay();
    const existingRun = await idbGet('meta', `run:${CONFIG.datasetSha256}`);
    if (existingRun) throw new Error(`A coleta nova ja foi criada em ${existingRun.folder_name}. Use await ClubEFT7.retomar(); iniciar() nao apaga nem reinicia essa fila.`);
    updateOverlay({
      status: 'SELECIONE Downloads/coleta-efhub-dados-fotos.', done: 0, total: 1,
      counts: 'Escolha essa pasta comum ja criada. Nao escolha Downloads e nao escolha arquivo.',
    });
    const { run } = await selecionarPastaDaColeta();
    await getDatasetIds();
    await writeArtifact(1, '00-inicio-da-coleta.json', `${JSON.stringify({
      ...run,
      dataset_sha256: CONFIG.datasetSha256,
      expected_missing: CONFIG.expectedMissing,
      batch_size_max: CONFIG.batchSize,
      phase: 'data',
      network_started_before_this_file: false,
    }, null, 2)}\n`);
    console.info(`Pasta selecionada: Downloads/${run.folder_name}. Fila NOVA: ${CONFIG.expectedMissing} pendentes; nenhum checkpoint anterior foi usado.`);
    console.info('Iniciando automaticamente o primeiro lote da FASE DADOS. Fotos nao bloquearão os dados.');
    return retomar();
  }

  async function retomar(lote = null) {
    await requireCollectionFolder();
    const ids = await getDatasetIds();
    ensureOverlay();
    await repairCheckpointFailures();
    await migratePriorCollectedToPhotoPending();
    if (lote !== null) {
      if (!Number.isInteger(lote) || lote < 1 || lote > CONFIG.totalBatches) throw new Error(`Lote invalido: ${lote}.`);
      const selectedIds = new Set(idsForBatch(ids, lote));
      const selectedRecords = (await allDatasetRecords()).filter((record) => selectedIds.has(record.card_id));
      const selectedMap = new Map(selectedRecords.map((record) => [record.card_id, record]));
      if ([...selectedIds].some((id) => !dataIsComplete(selectedMap.get(id)))) return runDataBatch(lote);
      if ([...selectedIds].some((id) => photoIsPending(selectedMap.get(id)))) return runPhotoBatch(lote);
      return { complete: true, batch: lote };
    }
    const dataBatchNo = await firstPendingDataBatch(ids);
    if (dataBatchNo !== null) return runDataBatch(dataBatchNo);
    const photoBatchNo = await firstPendingPhotoBatch(ids);
    if (photoBatchNo !== null) return runPhotoBatch(photoBatchNo);
    updateOverlay({ status: 'FASE DADOS e FASE FOTOS concluidas.', done: 1, total: 1, counts: 'Manifesto final salvo na pasta exclusiva.' });
    return { complete: true, manifest: (await exportar(CONFIG.totalBatches)).finalState.manifest };
  }

  function pausar() {
    state.paused = true;
    console.info('Pausa solicitada. O card_id atual terminara ou preservara o estado in_progress; depois o lote sera exportado.');
  }

  async function repetirFalhas(batchNo = state.currentBatch) {
    if (!Number.isInteger(batchNo)) throw new Error('Informe o numero do lote: repetirFalhas(1).');
    const ids = await getDatasetIds();
    const batchIds = new Set(idsForBatch(ids, batchNo));
    const records = await allDatasetRecords();
    const failed = records.filter((record) => batchIds.has(record.card_id) && record.status === 'failed');
    for (const record of failed) await idbDelete('records', record.key);
    console.info(`${failed.length} falhas liberadas explicitamente para nova tentativa. Ambiguos, inativos e coletados foram preservados.`);
    return retomar(batchNo);
  }

  async function diagnosticar() {
    const ids = await getDatasetIds();
    const before = await allDatasetRecords();
    const detectedBeforeRepair = {
      v3_false_http_200: before.filter(isV3FalseHttp200FailureRecord).length,
      legacy_http_429: before.filter(isThrottleFailureRecord).length,
      transient_network_or_json: before.filter(isNonterminalNetworkFailureRecord).length,
    };
    const repaired = await repairCheckpointFailures();
    const after = await allDatasetRecords();
    const lists = statusCounts(ids, after);
    const remainingFailedReasons = Object.entries(after
      .filter((record) => record.status === 'failed')
      .reduce((acc, record) => {
        const key = `${record.reason ?? 'sem_reason'} | HTTP ${record.http_status ?? 'n/a'}`;
        acc[key] = (acc[key] ?? 0) + 1;
        return acc;
      }, {}))
      .map(([reason, count]) => ({ reason, count }));
    const report = {
      collector_schema: CONFIG.schemaVersion,
      network_executed_by_diagnostic: false,
      endpoint: `${CONFIG.requiredOrigin}/api/public/players/{card_id}`,
      endpoint_evidence: '179 respostas cruas locais e coletores anteriores confirmam a rota por card_id; os 36 incidentes receberam HTTP 200 nessa mesma rota.',
      root_cause: 'V3 classificava qualquer status nao listado, inclusive 200, como failed antes de chamar response.json().',
      detected_before_repair: detectedBeforeRepair,
      repaired_this_script_load: repaired,
      current: {
        expected_missing: CONFIG.expectedMissing,
        collected: lists.collected.length,
        failed: lists.failed.length,
        pending: lists.pending.length,
        ambiguous_excluded: lists.ambiguous_excluded.length,
        inactive_excluded: lists.inactive_excluded.length,
      },
      remaining_failed_reasons: remainingFailedReasons,
      safe_next_command_when_authorized: 'await ClubEFT7.retomar()',
    };
    console.error('DIAGNOSTICO V4: a V3 tratava HTTP 200 como failed antes do parsing. O endpoint por card_id estava correto.');
    console.table(report.detected_before_repair);
    console.table(report.current);
    console.info('Checkpoint reparado sem rede. Historico mantido em recovery_history.');
    return report;
  }

  async function resumo() {
    const ids = await getDatasetIds();
    const recovered = await repairCheckpointFailures();
    const migratedPhotos = await migratePriorCollectedToPhotoPending();
    const records = await allDatasetRecords();
    const lists = statusCounts(ids, records);
    const manifest = {
      expected_missing: CONFIG.expectedMissing,
      already_complete_excluded: CONFIG.alreadyCompleteExcluded,
      collected: lists.collected.length,
      failed: lists.failed.length,
      pending: lists.pending.length,
      ambiguous_excluded: lists.ambiguous_excluded.length,
      inactive_excluded: lists.inactive_excluded.length,
      checkpoint_repair: recovered,
      data_only_records_migrated_to_photo_pending_now: migratedPhotos,
      data_payloads_saved: records.filter((record) => record.result?.payload).length,
      photos_downloaded: records.filter((record) => record.result?.photo_download?.status === 'downloaded').length,
      photos_download_triggered_unverified: records.filter((record) => record.result?.photo_download?.status === 'download_triggered_unverified').length,
      photos_unavailable: records.filter((record) => record.result?.photo_download?.status === 'unavailable').length,
      photos_pending: records.filter((record) => record.result?.photo_download?.status === 'pending').length,
      cooldown: await getCooldown(),
    };
    console.table(manifest);
    return manifest;
  }

  globalThis.ClubEFT7 = Object.freeze({
    iniciar,
    retomar,
    pausar,
    exportar,
    repetirFalhas,
    diagnosticar,
    resumo,
    CONFIG,
    __test: Object.freeze({
      stableStringify, normalizeCardId, validatePhoto, validatePayload,
      classifyHttp, classifyImageHttp, idsForBatch, statusCounts, batchLabel,
      structuredPayloadWithoutEfootballDbOwnedFields, photoFileName,
      dataIsComplete, photoIsPending, phaseCounts,
      decodeEmbeddedIdsText, validateEmbeddedDataset,
      parseRetryAfter, computeBackoffMs, computeThrottleCooldownMs,
      buildThrottleDecision, isThrottleFailureRecord, recoverThrottleRecord,
      isV3FalseHttp200FailureRecord, isNonterminalNetworkFailureRecord,
      checkpointRecoveryKind, recoverCheckpointRecord,
    }),
  });

  console.info('%cColetor T7 V6 carregado. Nenhuma rede foi iniciada.', 'font-weight:bold;color:#22c55e');
  console.info('Diagnostico e reparo do checkpoint, sem rede: await ClubEFT7.diagnosticar()');
  console.info('Lista de IDs embutida; nenhum seletor de arquivo sera aberto.');
  console.info('Primeira vez: await ClubEFT7.iniciar() — escolha a pasta Downloads/coleta-efhub-dados-fotos, nao a pasta Downloads.');
  console.info('Retomada em uma linha: await ClubEFT7.retomar()');
})();
